<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { flip } from 'svelte/animate';
  import { fly } from 'svelte/transition';
  import { isActive, type ThreadView, type PreviewInfo } from '@ash/shared';
  import Icon from './Icon.svelte';
  import Menu from './Menu.svelte';
  let {threads,selected,info,connected,creating,readRuns,onSelect,onCreate,onUpdate,onClose}:{threads:ThreadView[];selected:string;info:PreviewInfo|null;connected:boolean;creating:boolean;readRuns:Record<string,string>;onSelect:(id:string)=>void;onCreate:()=>void;onUpdate:(id:string,change:{title?:string;isArchived?:boolean})=>Promise<boolean>;onClose:()=>void}=$props();
  let width=$state(260),archivedOpen=$state(false),now=$state(Date.now()),reduced=$state(false);
  let menu=$state<{thread:ThreadView;x:number;y:number}|null>(null),rename=$state(''),title=$state(''),saving=$state(false);
  let input=$state<HTMLInputElement>();
  const visible=$derived(threads.filter(thread=>!thread.isArchived)),archived=$derived(threads.filter(thread=>thread.isArchived));
  function age(value:string){const minutes=Math.max(0,Math.floor((now-Date.parse(value))/60000));return minutes<1?'just now':minutes<60?`${minutes}m`:minutes<1440?`${Math.floor(minutes/60)}h`:`${Math.floor(minutes/1440)}d`;}
  function setWidth(value:number){width=Math.min(400,Math.max(200,value));localStorage.setItem('ash-sidebar-width',String(width));}
  function resize(event:PointerEvent){const start=event.clientX,initial=width;const handle=event.currentTarget as HTMLElement;handle.setPointerCapture(event.pointerId);handle.onpointermove=e=>setWidth(initial+e.clientX-start);handle.onlostpointercapture=()=>{handle.onpointermove=null;};}
  async function beginRename(thread:ThreadView){rename=thread.id;title=thread.title;await tick();input?.focus();input?.select();}
  async function saveTitle(){if(!rename||!title.trim()||saving)return;saving=true;try{if(await onUpdate(rename,{title:title.trim()}))rename='';}finally{saving=false;}}
  function openMenu(event:MouseEvent,thread:ThreadView){event.preventDefault();const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();menu={thread,x:event.type==='contextmenu'?event.clientX:rect.left,y:event.type==='contextmenu'?event.clientY:rect.bottom};}
  onMount(()=>{const saved=Number(localStorage.getItem('ash-sidebar-width'));if(saved)setWidth(saved);archivedOpen=localStorage.getItem('ash-archive-open')==='true';const media=matchMedia('(prefers-reduced-motion: reduce)');reduced=media.matches;const changed=()=>reduced=media.matches;media.addEventListener('change',changed);const timer=setInterval(()=>now=Date.now(),30000);return()=>{clearInterval(timer);media.removeEventListener('change',changed);};});
</script>
<aside class="sidebar" style:width={`${width}px`} aria-label="Conversation sidebar">
  <div class="brand"><span>✳</span> ash <small>DEV</small><button class="icon hide" aria-label="Hide sidebar" title="Hide sidebar" onclick={onClose}><Icon name="sidebar"/></button></div>
  <div class="section-heading"><span>Conversations</span><button class="icon" aria-label="New conversation" title="New conversation · ⌘N" disabled={creating||!connected} onclick={onCreate}><Icon name="new"/></button></div>
  <nav aria-label="Threads">
    {#each visible as thread (thread.id)}<div onintrostart={event=>{event.currentTarget.removeAttribute("aria-hidden");event.currentTarget.inert=false;}} onoutrostart={event=>{event.currentTarget.setAttribute("aria-hidden","true");event.currentTarget.inert=true;}} animate:flip={{duration:reduced?0:240}} transition:fly={{x:-16,duration:reduced?0:180}}>{@render row(thread)}</div>{/each}
    {#if !visible.length}<p class="empty">No conversations yet</p>{/if}
    {#if archived.length}<button class="archive-heading" aria-expanded={archivedOpen} onclick={()=>{archivedOpen=!archivedOpen;localStorage.setItem('ash-archive-open',String(archivedOpen));}}>{archivedOpen?'▾':'▸'} Archived ({archived.length})</button>{#if archivedOpen}{#each archived as thread (thread.id)}{@render row(thread)}{/each}{/if}{/if}
  </nav>
  <details class="workspace"><summary>Developer info</summary><p>{info?.label??'Connecting…'}</p><p>{info?.profile==='preview'?'Persistent preview':'Disposable verification'}</p><p>{info?.model?.provider==='openai'?`OpenAI · ${info.model.model}`:'Deterministic test model · No external calls'}</p>{#if info?.model?.session}<p>{info.model.session.callsUsed}{#if info.model.session.maxCalls!==null} / {info.model.session.maxCalls}{/if} calls{#if info.model.session.expiresAt!==null} · expires {new Date(info.model.session.expiresAt).toLocaleTimeString()}{/if}</p>{/if}</details>
  <!-- Focusable separator follows the ARIA window-splitter keyboard pattern. -->
  <!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions -->
  <div class="resize" role="separator" tabindex="0" aria-label="Resize sidebar" aria-orientation="vertical" aria-valuemin="200" aria-valuemax="400" aria-valuenow={width} onpointerdown={resize} ondblclick={()=>setWidth(260)} onkeydown={e=>{if(['ArrowLeft','ArrowRight','Home'].includes(e.key)){e.preventDefault();setWidth(e.key==='Home'?260:width+(e.key==='ArrowRight'?10:-10));}}}></div>
</aside>
{#snippet row(thread:ThreadView)}
  {@const running=!!thread.latestRun&&isActive(thread.latestRun.status)}
  {@const unread=!!thread.latestRun&&!running&&readRuns[thread.id]!==thread.latestRun.id}
  <div class="row" class:selected={selected===thread.id} class:unread={unread&&selected!==thread.id}>
    {#if rename===thread.id}<form onsubmit={e=>{e.preventDefault();void saveTitle();}}><input aria-label="Conversation title" bind:this={input} bind:value={title} maxlength="160" disabled={saving} onkeydown={e=>{if(e.key==='Escape'){e.preventDefault();rename='';}}}/><button disabled={saving||!title.trim()} aria-label="Save title">Save</button><button type="button" aria-label="Cancel rename" onclick={()=>rename=''}>×</button></form>
    {:else}<button class="select" aria-label={thread.title} aria-current={selected===thread.id?'page':undefined} title={thread.title} oncontextmenu={e=>openMenu(e,thread)} onclick={()=>onSelect(thread.id)}><span class="title">{thread.title}</span><span class="activity">{#if running}<span class="dot pulse" role="status" aria-label="Response in progress"></span>{:else if unread&&selected!==thread.id}<span class="dot" aria-label="Unread response"></span>{/if}<time datetime={thread.updatedAt}>{age(thread.updatedAt)}</time></span></button><div class="row-actions"><button class="icon" aria-label={`${thread.isArchived?'Unarchive':'Archive'} ${thread.title}`} title={thread.isArchived?'Unarchive':'Archive'} onclick={()=>onUpdate(thread.id,{isArchived:!thread.isArchived})}><Icon name={thread.isArchived?'restore':'archive'} size={15}/></button><button class="icon" aria-label={`Actions for ${thread.title}`} title="Conversation actions" onclick={e=>openMenu(e,thread)}><Icon name="more" size={15}/></button></div>{/if}
  </div>
{/snippet}
{#if menu}{@const target=menu.thread}<Menu x={menu.x} y={menu.y} onClose={()=>menu=null} items={[{label:'Rename',action:()=>void beginRename(target)}]}/>{/if}
<style>
  .sidebar{position:relative;flex-shrink:0;background:#eceee7;border-right:1px solid #dde0d6;padding:34px 12px 52px;display:flex;flex-direction:column;min-width:200px;max-width:40vw}.brand{display:flex;align-items:center;gap:8px;font-size:28px;font-weight:600;padding:0 8px 24px}.brand>span{color:var(--accent);font-size:34px}.brand small{font-size:9px;letter-spacing:1px;color:#7b8970}.icon{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:5px;background:transparent;color:#73826b;padding:6px}.icon:hover{background:#dfe5d7}.hide{margin-left:auto}.section-heading{display:flex;justify-content:space-between;align-items:center;padding:0 6px 10px;font-size:11px;font-weight:600;letter-spacing:.6px;color:#6e7c62}nav{flex:1;overflow:auto;scrollbar-width:thin}.row{display:flex;position:relative;border-radius:7px;margin:2px 0}.row.selected{background:#dfe5d7}.row:hover{background:#e3e8dd}.select{display:flex;gap:8px;align-items:center;justify-content:space-between;min-width:0;flex:1;text-align:left;border:0;background:transparent;color:#596352;padding:12px 10px;font-size:12px}.title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.activity{display:flex;gap:5px;align-items:center;flex-shrink:0}time{font-size:9px;color:#89927e}.row-actions{display:flex;align-items:center;position:absolute;right:3px;top:6px;opacity:0;background:#e3e8dd;border-radius:5px}.selected .row-actions{background:#dfe5d7}.row:hover .row-actions,.row:focus-within .row-actions{opacity:1}.row:hover .activity,.row:focus-within .activity{visibility:hidden}.select{padding-right:12px}.row:hover .select,.row:focus-within .select{padding-right:64px}.unread .title{font-weight:600}.dot{width:6px;height:6px;border-radius:50%;background:var(--accent)}.pulse{animation:pulse 1.4s ease-in-out infinite}.archive-heading{display:block;text-align:left;width:100%;padding:20px 8px 10px;border:0;background:transparent;color:#7c8973;font-size:10px}.workspace{padding:15px 8px 0;font-size:10px;color:#838b7d;line-height:1.5}.workspace summary{cursor:pointer}.workspace p{margin:7px 0}.empty{font-size:12px;color:#89927e;padding:10px}.resize{position:absolute;right:-3px;top:0;bottom:0;width:6px;cursor:col-resize;z-index:3;touch-action:none}.resize:hover{background:#75886925}form{display:flex;gap:4px;padding:7px;width:100%}input{width:100%;min-width:0;border:1px solid #a9b59e;border-radius:4px;background:#fafcf5;padding:6px;font:inherit;font-size:12px}form button{border:0;background:transparent;color:var(--accent);font-size:10px}@keyframes pulse{50%{opacity:.3}}@media(prefers-reduced-motion:reduce){.pulse{animation:none}}
</style>
